// P1 (revised 2026-11-11): Op catalog with ACTION / CONDITION separation.
// Pure data: NO runtime dispatch changes. Authoritative sources:
//   SEQUENCE_ACTION_FIELDS (574) and SEQUENCE_CONDITION_FIELDS (101) from sequenceContract.ts.
// Format: FAMILY-### for actions, Q-### for conditions. Variants stay as params.
// Backward compatible: all 184 previously-issued action codes are unchanged.
// See docs/op-code-system.md and docs/op-code-unindexed.md.

export type OpFamily = "A" | "C" | "D" | "G" | "H" | "M" | "P" | "S" | "T" | "X" | "Q";
export type OpKind = "action" | "condition" | "dual" | "internal" | "deprecatedCondition";

export interface OpEntry {
  op: string;
  code: string;
  family: OpFamily;
  familyLabel: string;
  kind: OpKind;
  /** For dual names: the Q-code to use when this name appears in c() condition context. */
  conditionCode?: string;
  /** Deprecated codes kept for old references; do not use for new lookups. */
  deprecatedCode?: string;
  declaredIn: ("action" | "condition")[];
}

export const OP_FAMILY_LABEL: Record<OpFamily, string> = {
  A: "能力／面板",
  C: "條件／查詢",
  D: "傷害",
  G: "防護／存活",
  H: "體力",
  M: "印記／標記",
  P: "資源／PP",
  S: "異常",
  T: "回合／時點",
  X: "流程／特殊",
  Q: "條件判斷",
};

