export const OP_CODES = Object.values(OP_CATALOG).filter(e=>e.kind!=="deprecatedCondition").map(e=>e.code);
export const CONDITION_CODES = Object.values(CONDITION_CATALOG).map(e=>e.code);
export const OP_CODE_TO_NAME: Record<string,string> = Object.fromEntries(
  Object.values(OP_CATALOG).filter(e=>e.kind!=="deprecatedCondition").map(e=>[e.code,e.op]));

export function opCode(op:string, context?: "action" | "condition"): string | undefined {
  const cond = CONDITION_CATALOG[op]?.code;
  const e = OP_CATALOG[op];
  // Condition context always resolves to the Q-code, even if the name has no
  // OP_CATALOG entry (many conditions only live in SEQUENCE_CONDITION_FIELDS).
  if (context === "condition") return cond ?? e?.conditionCode ?? (e?.kind === "condition" ? e.code : undefined);
  if (!e) return undefined;
  return e.kind === "deprecatedCondition" ? undefined : e.code;
}
export function opByCode(code:string): string | undefined { return OP_CODE_TO_NAME[code] ?? Object.values(CONDITION_CATALOG).find(e=>e.code===code)?.op; }
export function opsByFamily(f:OpFamily): OpEntry[] { return Object.values(OP_CATALOG).filter(e=>e.family===f); }
export function isConditionOp(op:string): boolean { return !!CONDITION_CATALOG[op]; }
